const d = msg.payload;
msg.power = { payload: d.power_w || 0 };
msg.irms = { payload: parseFloat((d.irms_a || 0).toFixed(2)) };
msg.cycle = { payload: d.cycle_active ? '🔴 EN CICLO: ' + (d.part_id || '') : '⚪ Sin ciclo' };
msg.mode = { payload: d.simulated ? '🟡 SIMULACIÓN' : '🟢 REAL' };
msg.payload = d.power_w || 0;
return msg;

const d = msg.payload;
msg.payload = '🟢 Online — ' + (d.device || '') + ' | RSSI: ' + (d.rssi || 0) + ' dBm | Uptime: ' + Math.floor((d.uptime || 0)/60) + ' min';
return msg;

const disponibilidad = 0.90 + (Math.random() * 0.08);
const rendimiento = 0.88 + (Math.random() * 0.10);
const calidad = 0.95 + (Math.random() * 0.04);
const oee = disponibilidad * rendimiento * calidad;
msg.payload = parseFloat((oee * 100).toFixed(1));
msg.disponibilidad = parseFloat((disponibilidad * 100).toFixed(1));
msg.rendimiento = parseFloat((rendimiento * 100).toFixed(1));
msg.calidad = parseFloat((calidad * 100).toFixed(1));
return msg;

const d = msg.payload;
if (!d) return null;

const ctx = context.global;
if (!ctx.get('plc_init')) {
    ctx.set('plc_init', true);
    ctx.set('estampado_prev', false);
    ctx.set('cognex_in_prev', false);
    ctx.set('aprobada_prev', false);
    ctx.set('boton_verde_prev', false);
    ctx.set('cognex_ts_start', null);
    ctx.set('piezas_procesadas', 0);
    ctx.set('piezas_aprobadas', 0);
    ctx.set('piezas_rechazadas', 0);
    ctx.set('ciclos_tiempos', []);
    ctx.set('turno_inicio', Date.now());
}

// Reset turno cada 8 horas
const turnoInicio = ctx.get('turno_inicio') || Date.now();
if (Date.now() - turnoInicio > 8 * 3600 * 1000) {
    ctx.set('piezas_procesadas', 0);
    ctx.set('piezas_aprobadas', 0);
    ctx.set('piezas_rechazadas', 0);
    ctx.set('ciclos_tiempos', []);
    ctx.set('turno_inicio', Date.now());
}

// Estado básico
const killswitch     = d.C2_Killswitch     || false;
const modo_auto      = killswitch;
const cobot_activo   = (d.M_Ci1_cobot || false) || (d.M_Ci2_cobot || false) || (d.M_Ci3_cobot || false);
const aprobada       = (d.Cognex_out0 || false) || (d.Cognex_out1 || false);
const estampado_down = d.C2_Estampado_Down || false;
const cognex_in      = d.Cognex_in0        || false;
const boton_verde    = d.C2_Boton_Verde   || false;

// Flanco descendente Estampado_Down → pieza procesada
const estampado_prev = ctx.get('estampado_prev');
if (estampado_prev === true && estampado_down === false) {
    const piezas = (ctx.get('piezas_procesadas') || 0) + 1;
    ctx.set('piezas_procesadas', piezas);

    const cognexTs = ctx.get('cognex_ts_start');
    if (cognexTs) {
        const tciclo = (Date.now() - cognexTs) / 1000;
        let ciclos = ctx.get('ciclos_tiempos') || [];
        ciclos.push(tciclo);
        if (ciclos.length > 20) ciclos = ciclos.slice(-20);
        ctx.set('ciclos_tiempos', ciclos);
        ctx.set('cognex_ts_start', null);
    }

}
ctx.set('estampado_prev', estampado_down);

// Flanco ascendente Cognex_in0 → inicio de ciclo
const cognex_prev = ctx.get('cognex_in_prev');
if (cognex_prev === false && cognex_in === true) {
    ctx.set('cognex_ts_start', Date.now());
}
ctx.set('cognex_in_prev', cognex_in);

// Flanco ascendente aprobada (Cognex_out0 OR Cognex_out1)
const aprobada_prev = ctx.get('aprobada_prev');
if (aprobada_prev === false && aprobada === true) {
    ctx.set('piezas_aprobadas', (ctx.get('piezas_aprobadas') || 0) + 1);
}
ctx.set('aprobada_prev', aprobada);

// Flanco ascendente Boton_Verde AND Pieza_rechazada → rechazo confirmado por operador
const rechazada_signal = d.Pieza_rechazada || false;
const boton_verde_prev = ctx.get('boton_verde_prev');
if (boton_verde_prev === false && boton_verde === true && rechazada_signal) {
    ctx.set('piezas_rechazadas', (ctx.get('piezas_rechazadas') || 0) + 1);
}
ctx.set('boton_verde_prev', boton_verde);

// KPIs calculados
const piezas_procesadas = ctx.get('piezas_procesadas') || 0;
const piezas_aprobadas  = ctx.get('piezas_aprobadas')  || 0;
const piezas_rechazadas = ctx.get('piezas_rechazadas') || 0;
const ciclos = ctx.get('ciclos_tiempos') || [];
const tiempo_ciclo_s          = ciclos.length > 0 ? ciclos[ciclos.length - 1] : 0;
const tiempo_ciclo_promedio_s = ciclos.length > 0 ? ciclos.reduce((a,b) => a+b,0) / ciclos.length : 0;
const oee = piezas_procesadas > 0 ? (piezas_aprobadas / piezas_procesadas) * 100 : 0;

// Output 1: señales rápidas (publicar cada ciclo)
const msgFast = { payload: {
    killswitch:     killswitch,
    modo_auto:      modo_auto,
    emergencia:     !killswitch,
    cobot_activo:   cobot_activo,
    boton_verde:    boton_verde,
    estampado_up:   d.C2_Estampado_Up    || false,
    estampado_down: estampado_down,
    bandas: {
        banda1:   d.C2_Banda_1        || false,
        banda2:   d.C2_Banda_2        || false,
        banda3:   d.C2_Banda_3        || false,
        banda4:   d.C2_Banda_4        || false,
        enfrente: d.C2_Banda_Enfrente || false,
        atras:    d.C2_Bandas_Atras   || false
    },
    estaciones: {
        taladro1:  d.C2_Taladro_1  || false,
        taladro2:  d.C2_Taladro_2  || false,
        martillo1: d.C2_Martillo_1 || false,
        martillo2: d.C2_Martillo_2 || false
    },
    cognex: {
        foto:      cognex_in,
        aprobada:  aprobada,
        rechazada: d.Pieza_rechazada || false
    },
    semaforo: {
        verde:        d.C2_Verde_Celda  || false,
        rojo:         d.C2_Rojo_Celda   || false,
        azul:         d.C2_Azul_Celda   || false,
        cuadro_verde: d.C2_Cuadro_Verde || false,
        cuadro_rojo:  d.C2_Cuadro_Rojo  || false
    },
    ts: new Date().toISOString()
}};

// Output 2: KPIs — solo si cambiaron los contadores
const kpiStr = JSON.stringify({ piezas_procesadas, piezas_aprobadas, piezas_rechazadas });
const lastKpiStr = ctx.get('lastKpiStr') || '';
let msgKpis = null;
if (kpiStr !== lastKpiStr) {
    ctx.set('lastKpiStr', kpiStr);
    msgKpis = { payload: {
        kpis: {
            piezas_procesadas:       piezas_procesadas,
            piezas_aprobadas:        piezas_aprobadas,
            piezas_rechazadas:       piezas_rechazadas,
            tiempo_ciclo_s:          Math.round(tiempo_ciclo_s * 10) / 10,
            tiempo_ciclo_promedio_s: Math.round(tiempo_ciclo_promedio_s * 10) / 10,
            oee:                     Math.round(oee * 10) / 10
        },
        ts: new Date().toISOString()
    }};
}

return [msgFast, msgKpis];

const d = msg.payload;
const ctx = context.global;
const now = Date.now();

// Escribir solo si hubo cambio O cada 10 segundos
const lastWrite = ctx.get('lastInfluxWriteCelda') || 0;
const lastHash  = ctx.get('lastStateHashCelda')   || '';
const stateHash = JSON.stringify({
    kill: d.killswitch, auto: d.modo_auto, cobot: d.cobot_activo,
    e_down: d.estampado_down, e_up: d.estampado_up,
    piezas: d.kpis.piezas_procesadas
});

if ((now - lastWrite < 10000) && stateHash === lastHash) return null;
ctx.set('lastInfluxWriteCelda', now);
ctx.set('lastStateHashCelda', stateHash);

const k = d.kpis;
const b = (v) => v ? 1 : 0;

const fields = [
    `killswitch=${b(d.killswitch)}i`,
    `modo_auto=${b(d.modo_auto)}i`,
    `emergencia=${b(d.emergencia)}i`,
    `cobot_activo=${b(d.cobot_activo)}i`,
    `estampado_up=${b(d.estampado_up)}i`,
    `estampado_down=${b(d.estampado_down)}i`,
    `banda1=${b(d.bandas.banda1)}i`,
    `banda2=${b(d.bandas.banda2)}i`,
    `banda3=${b(d.bandas.banda3)}i`,
    `banda4=${b(d.bandas.banda4)}i`,
    `banda_enfrente=${b(d.bandas.enfrente)}i`,
    `bandas_atras=${b(d.bandas.atras)}i`,
    `taladro1=${b(d.estaciones.taladro1)}i`,
    `taladro2=${b(d.estaciones.taladro2)}i`,
    `martillo1=${b(d.estaciones.martillo1)}i`,
    `martillo2=${b(d.estaciones.martillo2)}i`,
    `cognex_foto=${b(d.cognex.foto)}i`,
    `cognex_aprobada=${b(d.cognex.aprobada)}i`,
    `pieza_rechazada=${b(d.cognex.rechazada)}i`,
    `semaforo_verde=${b(d.semaforo.verde)}i`,
    `semaforo_rojo=${b(d.semaforo.rojo)}i`,
    `semaforo_azul=${b(d.semaforo.azul)}i`,
    `piezas_procesadas=${k.piezas_procesadas}i`,
    `piezas_aprobadas=${k.piezas_aprobadas}i`,
    `piezas_rechazadas=${k.piezas_rechazadas}i`,
    `tiempo_ciclo_s=${k.tiempo_ciclo_s}`,
    `tiempo_ciclo_promedio_s=${k.tiempo_ciclo_promedio_s}`,
    `oee=${k.oee}`
].join(',');

msg.payload = `celda3105_estado,planta=celda3105 ${fields} ${now}`;
msg.headers = { 'Content-Type': 'text/plain; charset=utf-8' };
return msg;

